export async function main(ns) {
  const visited = new Set();
  const nuked = [];

  // Recursively scan all servers
  function scan(srv) {
    if (visited.has(srv)) return;
    visited.add(srv);

    const ports = ns.getServerNumPortsRequired(srv);
    const hackLvl = ns.getServerRequiredHackingLevel(srv);

    // Nuke if 0 ports required
    if (ports === 0) {
      ns.nuke(srv);
      nuked.push(srv);
    }

    // Continue scanning
    const neighbors = ns.scan(srv);
    for (const next of neighbors) {
      scan(next);
    }
  }

  scan('home');

  // Find best target among nuked servers
  let target = 'n00dles';
  let maxMoney = 0;
  const playerHack = ns.getHackingLevel();

  for (const srv of nuked) {
    const reqHack = ns.getServerRequiredHackingLevel(srv);
    if (reqHack <= playerHack) {
      const money = ns.getServerMaxMoney(srv);
      if (money > maxMoney) {
        maxMoney = money;
        target = srv;
      }
    }
  }

  // Ensure n00dles is nuked
  ns.nuke('n00dles');

  // Main loop: weaken, grow, hack
  while (true) {
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (sec > minSec + 5) {
      await ns.weaken(target);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }
  }
}

